const path=require("path"),fs=require("fs"),configPath=path.resolve(__dirname,"db.config.json");let config;try{config=JSON.parse(fs.readFileSync(configPath,"utf8"))}catch(e){process.exit(1)}function getSourceConfig(e={}){const t=config.source;return{user:e.user||t.user,password:e.password||t.password,server:e.server||t.server,database:e.database||t.database,port:e.port||t.port,options:{encrypt:t.options?.encrypt??!1,trustServerCertificate:t.options?.trustServerCertificate??!0,...e.options}}}function getTargetConfig(e={}){const t=config.target;return{host:e.host||process.env.DB_TARGET_HOST||t.host,user:e.user||process.env.DB_TARGET_USER||t.user,password:e.password||process.env.DB_TARGET_PASSWORD||t.password,database:e.database||process.env.DB_TARGET_DATABASE||t.database,charset:e.charset||t.charset||"utf8mb4"}}function getMigrationConfig(){return{clinicId:config.migration?.clinic_id||1,batchSize:config.migration?.batch_size||100,dataOutputPath:path.resolve(__dirname,config.migration?.data_output_path||"./data/migration_data.json")}}function getAppKey(){return process.env.APP_KEY?process.env.APP_KEY:config.encryption?.app_key}function getFullConfig(){return{source:getSourceConfig(),target:getTargetConfig(),migration:getMigrationConfig(),appKey:getAppKey()}}module.exports={getSourceConfig:getSourceConfig,getTargetConfig:getTargetConfig,getMigrationConfig:getMigrationConfig,getAppKey:getAppKey,getFullConfig:getFullConfig,_rawConfig:config};